_PREMIUM_ID_CYCLE = _itertools.cycle(PREMIUM_CUSTOM_EMOJI_POOL)


def NEXT_PREMIUM_EMOJI_ID() -> str:
    return next(_PREMIUM_ID_CYCLE)


_VALID_HTML_TAG_RE = re.compile(
    r"(<tg-emoji\s+emoji-id=['\"]\d+['\"]>.*?</tg-emoji>|<b>|</b>|<i>|</i>|<u>|</u>|<s>|</s>|<code>|</code>|<pre>|</pre>)",
    re.DOTALL,
)
_STRIP_TG_EMOJI_RE = re.compile(r"<tg-emoji\s+emoji-id=['\"]\d+['\"]>(.*?)</tg-emoji>", re.DOTALL)
_DYNAMIC_EMOJI_RE = re.compile(
    r"(?:[\U0001F1E6-\U0001F1FF]{2}"
    r"|(?:[\U0001F300-\U0001FAFF\u2600-\u27BF])(?:[\uFE0E\uFE0F]|[\U0001F3FB-\U0001F3FF])?"
    r"(?:\u200D(?:[\U0001F300-\U0001FAFF\u2600-\u27BF])(?:[\uFE0E\uFE0F]|[\U0001F3FB-\U0001F3FF])?)*)"
)


def _plain_telegram_field(text: str) -> str:
    """Unwrap <tg-emoji> tags back to clean emojis for plain-text API calls (titles/descriptions/bot name)."""
    return _STRIP_TG_EMOJI_RE.sub(r"\1", str(text or ""))


def _prepare_premium_html(raw_text: str) -> str:
    """
    Ensure valid HTML entities for every outgoing message:
    - Keeps <tg-emoji emoji-id="...">...</tg-emoji>, <b>, <code>, etc. intact
    - Safely escapes literal <, >, & in <target>, <name>, >=, dynamic user input, error strings
    - Auto-upgrades any dynamic runtime emojis into unique animated <tg-emoji> IDs
    - Respects Telegram's max 95 custom entities per message ceiling so large blocks never fail
    """
    parts = _VALID_HTML_TAG_RE.split(str(raw_text or ""))
    out = []
    entity_count = 0
    for idx, chunk in enumerate(parts):
        if idx % 2 == 1:
            if chunk.startswith("<tg-emoji"):
                entity_count += 1
                if entity_count <= 95:
                    out.append(chunk)
                else:
                    out.append(_STRIP_TG_EMOJI_RE.sub(r"\1", chunk))
            else:
                out.append(chunk)
        else:
            escaped = _html.escape(chunk, quote=False)

            def _dyn_sub(m):
                nonlocal entity_count
                entity_count += 1
                if entity_count <= 95:
                    return f'<tg-emoji emoji-id="{NEXT_PREMIUM_EMOJI_ID()}">{m.group(0)}</tg-emoji>'
                return m.group(0)

            out.append(_DYNAMIC_EMOJI_RE.sub(_dyn_sub, escaped))
    return "".join(out)


def _make_btn(text: str, callback_data: str, style: str, icon_id: str) -> InlineKeyboardButton:
    if "icon_custom_emoji_id" in InlineKeyboardButton.__init__.__code__.co_varnames:
        return InlineKeyboardButton(
            text,
            callback_data=callback_data,
            style=style,
            icon_custom_emoji_id=icon_id,
        )
    return InlineKeyboardButton(text, callback_data=callback_data)


