async def _patched_send_message(self, chat_id, text, *args, **kwargs):
    kwargs.setdefault("parse_mode", ParseMode.HTML)
    html_text = _prepare_premium_html(text) if kwargs.get("parse_mode") == ParseMode.HTML else text
    try:
        return await _orig_send_message(self, chat_id, html_text, *args, **kwargs)
    except _TgBadRequest:
        clean_text = _html.escape(_plain_telegram_field(text), quote=False)
        kwargs.pop("reply_markup", None)
        return await _orig_send_message(self, chat_id, clean_text, *args, **kwargs)


async def _patched_reply_text(self, text, *args, **kwargs):
    kwargs.setdefault("parse_mode", ParseMode.HTML)
    html_text = _prepare_premium_html(text) if kwargs.get("parse_mode") == ParseMode.HTML else text
    try:
        return await _orig_reply_text(self, html_text, *args, **kwargs)
    except _TgBadRequest:
        clean_text = _html.escape(_plain_telegram_field(text), quote=False)
        kwargs.pop("reply_markup", None)
        return await _orig_reply_text(self, clean_text, *args, **kwargs)


async def _patched_edit_text(self, text, *args, **kwargs):
    kwargs.setdefault("parse_mode", ParseMode.HTML)
    html_text = _prepare_premium_html(text) if kwargs.get("parse_mode") == ParseMode.HTML else text
    try:
        return await _orig_edit_text(self, html_text, *args, **kwargs)
    except _TgBadRequest:
        clean_text = _html.escape(_plain_telegram_field(text), quote=False)
        kwargs.pop("reply_markup", None)
        return await _orig_edit_text(self, clean_text, *args, **kwargs)


async def _patched_set_chat_title(self, chat_id, title, *args, **kwargs):
    return await _orig_set_chat_title(self, chat_id, _plain_telegram_field(title)[:128], *args, **kwargs)


async def _patched_set_chat_description(self, chat_id, description=None, *args, **kwargs):
    return await _orig_set_chat_description(self, chat_id, _plain_telegram_field(description)[:255], *args, **kwargs)


async def _patched_set_my_name(self, name=None, *args, **kwargs):
    return await _orig_set_my_name(self, name=_plain_telegram_field(name)[:64], *args, **kwargs)


