            f"├ <tg-emoji emoji-id='5249342839153791931'>💬</tg-emoji> 𝙈𝙚𝙨𝙨𝙖𝙜𝙚𝙨 𝙎𝙚𝙣𝙩: {GLOBAL_STATS['messages_sent']:,}\n"
